function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // door
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);

  // door handle
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+25, 10, 0, 2*Math.PI);
  ctx.fill();

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-100, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-100, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+30);
  ctx.lineTo(W/2-100-20, H/2+40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+30);
  ctx.lineTo(W/2-100+20, H/2+40);
  ctx.stroke();

  // hand movement
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+50);
  ctx.lineTo(W/2-50+20*Math.sin(t), H/2+25);
  ctx.stroke();

  // checking motion
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText(Math.floor(t)%2 === 0 ? 'Check' : 'Recheck', W/2, H/2-70);

  ctx.restore();
}
